<?php require_once __DIR__.'/../../includes/bootstrap.php';$u=require_role('Administrator','Management','Event');verify_csrf($_POST['csrf']??'');$id=(int)$_POST['id'];$action=$_POST['action'];$pdo=db();$s=$pdo->prepare('SELECT * FROM booking_change_requests WHERE id=?');$s->execute([$id]);$r=$s->fetch();if(!$r||$r['status']!=='pending')redirect('admin/bookings/index.php');if(!in_array($action,['approve','reject'],true))redirect('admin/bookings/index.php');try{$pdo->beginTransaction();$status=$action==='approve'?'approved':'rejected';if($status==='approved'){if($r['proposed_start_at']&&$r['proposed_end_at']){$q=$pdo->prepare("SELECT COUNT(*) FROM event_venues ev JOIN events e ON e.id=ev.event_id WHERE ev.venue_id=COALESCE(?,(SELECT venue_id FROM event_venues WHERE event_id=(SELECT event_id FROM bookings WHERE id=?) LIMIT 1)) AND e.id<>(SELECT event_id FROM bookings WHERE id=?) AND e.status IN ('pending','confirmed') AND e.start_at < ? AND e.end_at > ?");$q->execute([$r['proposed_venue_id'],$r['booking_id'],$r['booking_id'],$r['proposed_end_at'],$r['proposed_start_at']]);if((int)$q->fetchColumn()>0)throw new RuntimeException('Requested change conflicts with another event.');}$eid=(int)$pdo->query('SELECT event_id FROM bookings WHERE id='.$r['booking_id'])->fetchColumn();if($r['proposed_start_at']&&$r['proposed_end_at'])$pdo->prepare('UPDATE events SET start_at=?,end_at=? WHERE id=?')->execute([$r['proposed_start_at'],$r['proposed_end_at'],$eid]);if($r['proposed_venue_id']){$pdo->prepare('DELETE FROM event_venues WHERE event_id=?')->execute([$eid]);$pdo->prepare('INSERT INTO event_venues(event_id,venue_id) VALUES(?,?)')->execute([$eid,$r['proposed_venue_id']]);}}$pdo->prepare('UPDATE booking_change_requests SET status=?,reviewed_by=?,reviewed_at=NOW(),review_note=? WHERE id=?')->execute([$status,$u['id'],$status==='approved'?'Change request approved.':'Change request rejected.',$id]);$pdo->prepare('INSERT INTO booking_change_history(booking_id,field_name,old_value,new_value,changed_by) VALUES(?,?,?,?,?)')->execute([$r['booking_id'],'change_request',$r['reason'],$status,$u['id']]);$uid=(int)$pdo->query('SELECT user_id FROM bookings WHERE id='.$r['booking_id'])->fetchColumn();$pdo->prepare('INSERT INTO notifications(user_id,type,title,message,link_url) VALUES(?,?,?,?,?)')->execute([$uid,'booking_change','Booking change '.$status,'Your booking change request has been '.$status.'.',url('user/bookings/view.php?id='.$r['booking_id'])]);audit('change_request_'.$action,'booking_change_request',$id);$pdo->commit();flash('success','Change request updated.');redirect('admin/bookings/view.php?id='.$r['booking_id']);}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();flash('error',$e->getMessage());redirect('admin/bookings/view.php?id='.$r['booking_id']);}
